private processRequestWithToken(token: string, req:
HttpRequest<any>,
next: HttpHandler) {
if (!!token && this.isSameOriginUrl(req)) {
req = req.clone({
setHeaders: {
Authorization: `Bearer ${token}`
}
});
}
return next.handle(req);
}
private isSameOriginUrl(req: any) {
// It's an absolute url with the same origin.
if (req.url.startsWith(`${window.location.origin}/`)) {
return true;
}
// It's a protocol relative url with the same origin.
// For example: //www.example.com/api/Products
if (req.url.startsWith(`//${window.location.host}/`)) {
return true;
}
// It's a relative url like /api/Products
if (/^\/[^\/].*/.test(req.url)) {
return true;
}
// It's an absolute or protocol relative url that
// doesn't have the same origin.
return false;
}
}
As we can see, the AuthorizeInterceptor implements the HttpInterceptor
interface by defining an intercept method. That method's job is to intercept all the
outgoing HTTP requests and conditionally add the JWT Bearer token to their HTTP
headers; this condition is determined by the isSameOriginUrl() internal method,
which will return true only if the request is addressed to an URL with the same
origin of the Angular app.
Authentication and Authorization Chapter 10
[ 553 ]
Just like any other Angular class, the AuthorizeInterceptor needs to be properly
configured within an NgModule in order to work; since it needs to inspect any HTTP
request — including those not part of the authorization API — it has been configured in
the AppModule, the root-level NgModule, or the AuthSample app.
To see the actual implementation, open the /ClientApp/src/app/app.module.ts
file and look at the providers section:
// ...
providers: [
{ provide: HTTP_INTERCEPTORS, useClass: AuthorizeInterceptor, multi:
true }
],
// ...
The multi: true property that we can see in the preceding code is a required
setting, because HTTP_INTERCEPTORS is a multi-provider token that is expecting
to inject an array of multiple values, rather than a single one.
For additional information about HTTP interceptors, take a look at
the following URLs:
https:/ / angular. io/ api/ common/ http/ HttpInterceptor
https:/ / angular. io/ api/ common/ http/ HTTP_ INTERCEPTORS
